panels.script:
const ngu = window.ngu;
const root = document.getElementById('tk-root');

function el(tag, cls, text) {
  const n = document.createElement(tag);
  if (cls) n.className = cls;
  if (text != null) n.textContent = text;
  return n;
}

// 状态 -> 一个小色点。颜色比文字更快被眼睛读到，而票板就是给扫一眼用的。
const DOT = {
  running: '#2f7d32',
  delivered: '#b4632a',
  partial: '#8a6d1f',
  stuck: '#c62828',
  closed: '#9a8d7c',
};

function reportHeight() {
  if (!document.body) return;
  let bottom = 0;
  const base = document.body.getBoundingClientRect().top;
  for (const node of document.body.querySelectorAll('*')) {
    if (node.hidden) continue;
    const style = getComputedStyle(node);
    if (style.display === 'none' || style.visibility === 'hidden') continue;
    const r = node.getBoundingClientRect();
    if (r.width === 0 && r.height === 0) continue;
    if (r.bottom - base > bottom) bottom = r.bottom - base;
  }
  let h = Math.ceil(bottom);
  if (h <= 1) h = 0;
  parent.postMessage({ ngu: 'panel', panelId: 'ticket-board', requestId: null,
    cmd: 'panel:resize', args: { height: h } }, '*');
}

function paint(state) {
  if (!root) return;
  root.replaceChildren();
  const rows = (state && state.tickets) || [];
  if (!rows.length) {
    // 没有票就把整帧收起，不留一条空带把输入框往下推。
    document.body.style.display = 'none';
    reportHeight();
    return;
  }
  document.body.style.display = '';

  const head = el('div', 'tk-head');
  head.appendChild(el('span', 'tk-title', '票板'));
  const parts = [];
  if (state.running) parts.push(state.running + ' 在跑');
  if (state.delivered) parts.push(state.delivered + ' 待验收');
  if (state.partial) parts.push(state.partial + ' 做一半');
  if (state.stuck) parts.push(state.stuck + ' 卡住');
  head.appendChild(el('span', 'tk-summary', parts.join(' · ') || (rows.length + ' 张')));
  root.appendChild(head);

  const list = el('div', 'tk-list');
  for (const t of rows) {
    const row = el('div', 'tk-row');
    const dot = el('span', 'tk-dot');
    dot.style.background = DOT[t.state] || '#9a8d7c';
    row.appendChild(dot);
    row.appendChild(el('span', 'tk-id', t.id));
    row.appendChild(el('span', 'tk-goal', t.goal || ''));
    if (t.rounds > 1) row.appendChild(el('span', 'tk-rounds', 'r' + t.rounds));
    // 空转连击只在真的发生时出现。它不是判决，是一个让主代理多看一眼的信号。
    if (t.empty >= 2) row.appendChild(el('span', 'tk-empty', '空转' + t.empty));
    if (t.age) row.appendChild(el('span', 'tk-age', t.age));
    row.appendChild(el('span', 'tk-state s-' + (t.state || ''), t.state || ''));
    list.appendChild(row);
  }
  root.appendChild(list);
  reportHeight();
}

function scan(text) {
  if (typeof text !== 'string') return;
  const at = text.indexOf('<!--ticket-state ');
  if (at < 0) return;
  const end = text.indexOf('-->', at);
  if (end < 0) return;
  const raw = text.slice(at + '<!--ticket-state '.length, end);
  try { paint(JSON.parse(raw)); } catch (e) { /* 一条坏标记不该让面板坏掉 */ }
}

if (ngu && typeof ngu.on === 'function') {
  ngu.on('tool_end', function (ev) { scan(ev && ev.result); });
}

// 一开始没票：整帧收起。
document.body.style.display = 'none';

css:
.tk-head{display:flex;align-items:baseline;gap:8px;padding:2px 2px 5px;}
.tk-title{font-weight:600;color:#3a2e24;}
.tk-summary{color:#7d7264;font-size:11px;}
.tk-list{display:flex;flex-direction:column;gap:2px;max-height:220px;overflow:auto;}
.tk-row{display:flex;align-items:center;gap:7px;padding:4px 6px;border-radius:5px;background:#fffdf8;border:1px solid #eee5d6;}
.tk-row:hover{background:#f7f1e6;}
.tk-dot{width:7px;height:7px;border-radius:50%;flex:0 0 auto;}
.tk-id{font-family:ui-monospace,Menlo,Consolas,monospace;font-size:10.5px;color:#9a8d7c;flex:0 0 auto;}
.tk-goal{flex:1 1 auto;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#3a2e24;}
.tk-age{font-variant-numeric:tabular-nums;color:#7d7264;font-size:10.5px;flex:0 0 auto;}
.tk-state{font-size:10px;padding:1px 5px;border-radius:4px;flex:0 0 auto;}
.tk-state.s-running{background:#e8f5e9;color:#2f7d32;}
.tk-state.s-delivered{background:#fdf0e3;color:#b4632a;}
.tk-state.s-stuck{background:#fdecea;color:#c62828;}
.tk-state.s-closed{background:#f0ede8;color:#9a8d7c;}
.tk-rounds{font-size:10px;color:#9a8d7c;font-variant-numeric:tabular-nums;flex:0 0 auto;}
.tk-empty{font-size:10px;padding:1px 4px;border-radius:4px;background:#fff4d6;color:#8a6d1f;flex:0 0 auto;}
.tk-state.s-partial{background:#fdf6e0;color:#8a6d1f;}
